std::vector<int> vec = {1, 2, 3, 4, 5};
// Get a reverse iterator to the beginning of the reversed sequence
std::vector<int>::reverse_iterator rit = vec.rbegin();
// Get a reverse iterator to the end of the reversed sequence
std::vector<int>::reverse_iterator rend = vec.rend();

// Dereferencing the reverse iterator
*rit; // This will give the last element of the vector, which is 5.
